    let body;
    if(!consistent)body=`<p class="card-body">${{CALM:'이 앱이 살피는 합·충이 없는 구성입니다.',COORDINATE:'합이 있고 충은 없는 구성입니다.',FRICTION:'충이 있는 구성입니다.'}[r.relationContext]||'확정된 글자의 관계를 기준으로 읽습니다.'}</p>`;
    else if(!pairs.length)body='<p class="card-body">이 앱이 살피는 천간합·지지 육합·지지 육충 가운데 해당하는 짝이 없습니다.</p>';
